from fastapi import APIRouter, Depends, HTTPException
from models import Item
from deps import get_db

router = APIRouter()


@router.get("/")
def list_items(db: dict = Depends(get_db)):
    return db["items"]


@router.post("/")
def create_item(item: Item, db: dict = Depends(get_db)):
    item_dict = {"id": len(db["items"]) + 1, **item.model_dump()}
    db["items"].append(item_dict)
    return item_dict


@router.delete("/{item_id}")
def delete_item(item_id: int, db: dict = Depends(get_db)):
    items = db["items"]
    for i, item in enumerate(items):
        if item["id"] == item_id:
            items.pop(i)
            return {"deleted": True}
    raise HTTPException(status_code=404, detail="Item not found")

from fastapi import APIRouter, Depends
from models import User
from deps import get_db

router = APIRouter()


@router.get("/")
def list_users(db: dict = Depends(get_db)):
    return db["users"]


@router.post("/")
def create_user(user: User, db: dict = Depends(get_db)):
    user_dict = {"id": len(db["users"]) + 1, **user.model_dump()}
    db["users"].append(user_dict)
    return user_dict

from fastapi import FastAPI
from routers.items import router as items_router
from routers.users import router as users_router

app = FastAPI()

app.include_router(items_router, prefix="/items")
app.include_router(users_router, prefix="/users")


@app.get("/")
def read_root():
    return {"message": "Multi-Router API"}
